// Embeds the Leaflet map library (BSD-2-Clause) into src/leafletAssets.ts.
// Runs automatically after `npm install`.
const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const dist = path.join(root, 'node_modules', 'leaflet', 'dist');
const js = fs.readFileSync(path.join(dist, 'leaflet.js'), 'utf8');
const css = fs.readFileSync(path.join(dist, 'leaflet.css'), 'utf8');

fs.writeFileSync(
  path.join(root, 'src', 'leafletAssets.ts'),
  '// Generated by scripts/gen-leaflet.js from leaflet@1.9.4. Do not edit.\n' +
    'export const LEAFLET_JS = ' + JSON.stringify(js) + ';\n' +
    'export const LEAFLET_CSS = ' + JSON.stringify(css) + ';\n'
);
console.log('leafletAssets.ts generated');
